def set_language(language: str) -> str:
    global _LANGUAGE
    normalized = language if language in SUPPORTED_LANGUAGES else "ru"
    with _LOCK:
        _LANGUAGE = normalized
    return normalized


def get_language() -> str:
    with _LOCK:
        return _LANGUAGE


def tr(key: str, **values: Any) -> str:
    with _LOCK:
        language = _LANGUAGE
    text = _TRANSLATIONS.get(language, {}).get(key)
    if text is None:
        text = _TRANSLATIONS["ru"].get(key, key)
    try:
        return text.format(**values)
    except (KeyError, ValueError):
        return text
